#include <cstdio>
#include <iostream>
using namespace std;

long long modpow(long long base, long long exp, int mod) {
    long long result = 1;
    while (exp) {
        if (exp & 1) result = result * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return result;
}

bool isPrime(int value) {
    if (value < 2) return false;
    for (int i = 2; 1LL * i * i <= value; ++i)
        if (value % i == 0) return false;
    return true;
}

bool check(int base, int prime) {
    if (base == 0) return false;

    int phi = prime - 1;
    int value = phi;

    for (int factor = 2; 1LL * factor * factor <= value; ++factor) {
        if (value % factor == 0) {
            if (modpow(base, phi / factor, prime) == 1) return false;
            while (value % factor == 0) value /= factor;
        }
    }

    if (value > 1 && modpow(base, phi / value, prime) == 1)
        return false;

    return true;
}

int main() {
    int n, x;
    cin >> n >> x;
    ++n;

    if (!isPrime(n)) {
        puts("-1");
        return 0;
    }

    for (int i = x - 1; i >= 1; --i) {
        if (check(i % n, n)) {
            printf("%d\n", i);
            return 0;
        }
    }

    puts("-1");
    return 0;
}

